from pathlib import Path

source = Path('tools/ats_question_triage.py')
regression = Path('tests/test_ats_question_triage_regression.py')
immutable_tests = Path('tests/test_ats_question_triage.py')

if not source.is_file() or not immutable_tests.is_file():
 raise SystemExit('APPROVED_SOURCE_OR_IMMUTABLE_TEST_MISSING')
if regression.exists():
 raise SystemExit('REGRESSION_FILE_ALREADY_EXISTS_REQUIRES_INSPECTION')

original = source.read_text(encoding='utf-8')
old_guard = ''' if kind in {"checkbox","radio","select-one","select-multiple","textarea","file","password"}:
 return {"status":"human_review","reason":"nontrivial_control"}'''
new_guard = ''' # Only explicitly supported text-entry controls may represent verified
 # contact facts. Unsupported, hidden, and action controls fail closed.
 if kind not in {"text", "email", "tel", "url"}:
 return {"status":"human_review","reason":"nontrivial_control"}'''

if original.count(old_guard) != 1:
 raise SystemExit('SOURCE_GUARD_CHANGED_NO_MODIFICATION')

updated = original.replace(old_guard, new_guard)

regression_content = '''"""Public-fixture regression tests for conservative ATS control triage."""
import pytest

from tools.ats_question_triage import classify_field


@pytest.mark.parametrize("question,key", [
 ("Full name", "full_name"),
 ("Email", "email"),
 ("Phone", "phone"),
 ("LinkedIn", "linkedin"),
 ("GitHub", "github"),
])
@pytest.mark.parametrize("kind", [
 "hidden", "submit", "button", "reset", "number", "date",
 "datetime-local", "time", "color", "range", "search",
 "checkbox", "radio", "select-one", "select-multiple",
 "textarea", "file", "password", "unknown", "", None,
])
def test_unsupported_contact_controls_require_human_review(question, key, kind):
 result = classify_field(
 {"question": question, "label": question, "type": kind,
 "ambiguous": False},
 {key},
 )
 assert result == {
 "status": "human_review",
 "reason": "nontrivial_control",
 }


@pytest.mark.parametrize("question,kind,key", [
 ("Full name", "text", "full_name"),
 ("Email", "email", "email"),
 ("Phone", "tel", "phone"),
 ("LinkedIn", "url", "linkedin"),
 ("GitHub", "url", "github"),
 ("Email ✱", "email", "email"),
])
def test_supported_verified_contact_controls_remain_candidates(question, kind, key):
 result = classify_field(
 {"question": question, "label": question, "type": kind,
 "ambiguous": False},
 {key},
 )
 assert result == {"status": "verified_candidate", "profile_key": key}


def test_supported_contact_without_verified_fact_requires_review():
 result = classify_field(
 {"question": "Email", "label": "Email", "type": "email",
 "ambiguous": False},
 set(),
 )
 assert result == {
 "status": "human_review",
 "reason": "unverified_profile_fact",
 }


def test_ambiguous_verified_contact_still_requires_review():
 result = classify_field(
 {"question": "Email", "label": "Email", "type": "email",
 "ambiguous": True},
 {"email"},
 )
 assert result == {
 "status": "human_review",
 "reason": "ambiguous_question",
 }


def test_non_contact_text_never_becomes_verified_candidate():
 result = classify_field(
 {"question": "Referee email", "label": "Referee email",
 "type": "email", "ambiguous": False},
 {"email"},
 )
 assert result == {
 "status": "human_review",
 "reason": "unknown_question",
 }
'''

compile(updated, str(source), 'exec')
compile(regression_content, str(regression), 'exec')

try:
 source.write_text(updated, encoding='utf-8')
 regression.write_text(regression_content, encoding='utf-8')
except BaseException:
 source.write_text(original, encoding='utf-8')
 if regression.exists():
 regression.unlink()
 raise

print('ATS_TRIAGE_SOURCE_AND_REGRESSION_PREPARED')
print('EDITED_PATHS: tools/ats_question_triage.py, tests/test_ats_question_triage_regression.py')
print('IMMUTABLE_TESTS_UNCHANGED: tests/test_ats_question_triage.py')
print('MANDATORY_TEST_EXECUTION_DELEGATED_TO_ISOLATED_WORKER')
print('APPLICATION_SUBMISSIONS: 0')
